// NLCL game runtime for Unity: cross-module channels through the NLCL HTTP hub
// (POST {hub}/channel/<id> to publish, GET the same URL to read the latest
// message) plus a tiny flat-JSON reader/writer.  Generated by NLCL.
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.Text;
using UnityEngine;
using UnityEngine.Networking;

public class NlclHub : MonoBehaviour
{
    public class Ch
    {
        public string id, url, src, dst;
        public string[] fields;
        public float interval;
        public bool srcLocal, dstLocal;
        public double seen = -1;
    }

    public static NlclHub Instance;
    public static readonly Dictionary<string, object> Remote = new Dictionary<string, object>();  // "src.field" -> value
    static readonly Dictionary<string, bool> _lastBool = new Dictionary<string, bool>();
    readonly List<Ch> _channels = new List<Ch>();

    void Awake() { Instance = this; }

    public void Add(string id, string url, string src, string dst, string[] fields, int intervalMs, bool srcLocal, bool dstLocal)
    {
        Ch ch = new Ch { id = id, url = url, src = src, dst = dst, fields = fields,
                         interval = Mathf.Max(0.05f, intervalMs / 1000f), srcLocal = srcLocal, dstLocal = dstLocal };
        _channels.Add(ch);
        if (srcLocal) StartCoroutine(Publisher(ch));
        else if (dstLocal) StartCoroutine(Poller(ch));
    }

    // ---- remote values (other modules' properties) ------------------------
    public static float GetFloat(string src, string field, float d) { object v; return Remote.TryGetValue(src + "." + field, out v) ? NlclEntity.ToFloat(v) : d; }
    public static bool GetBool(string src, string field, bool d) { object v; return Remote.TryGetValue(src + "." + field, out v) ? NlclEntity.ToBool(v) : d; }
    public static string GetString(string src, string field, string d) { object v; return Remote.TryGetValue(src + "." + field, out v) ? NlclEntity.ToStr(v) : d; }

    // ---- sending ------------------------------------------------------------
    /// <summary>"send" action: publish now on every channel whose sender is e.</summary>
    public static void Send(NlclEntity e, string to, string[] fields)
    {
        if (Instance == null || e == null) return;
        bool sent = false;
        foreach (Ch ch in Instance._channels)
        {
            if (ch.src != e.nlclId) continue;
            if (!string.IsNullOrEmpty(to) && to != ch.dst && to != ch.id) continue;
            Instance.Emit(ch, fields ?? ch.fields);
            sent = true;
        }
        // no channel declared, but the receiver lives in this game: deliver directly
        if (!sent && !string.IsNullOrEmpty(to) && NlclWorld.Get<NlclEntity>(to) != null)
        {
            Ch direct = new Ch { id = e.nlclId + "_to_" + to, src = e.nlclId, dst = to,
                                 fields = fields ?? new string[0], srcLocal = true, dstLocal = true };
            Dictionary<string, object> payload = new Dictionary<string, object>();
            foreach (string f in direct.fields) payload[f] = e.NlclGet(f);
            Deliver(direct, payload);
        }
    }

    void Emit(Ch ch, string[] fields)
    {
        NlclEntity e = NlclWorld.Get<NlclEntity>(ch.src);
        if (e == null) return;
        Dictionary<string, object> payload = new Dictionary<string, object>();
        foreach (string f in fields) payload[f] = e.NlclGet(f);
        if (ch.dstLocal) { Deliver(ch, payload); return; }      // both ends in this game
        payload["channel"] = ch.id;
        payload["from"] = ch.src;
        StartCoroutine(Post(ch.url, NlclJson.Write(payload)));
    }

    IEnumerator Publisher(Ch ch)
    {
        while (true)
        {
            yield return new WaitForSeconds(ch.interval);
            Emit(ch, ch.fields);
        }
    }

    IEnumerator Post(string url, string json)
    {
        using (UnityWebRequest r = new UnityWebRequest(url, "POST"))
        {
            r.uploadHandler = new UploadHandlerRaw(Encoding.UTF8.GetBytes(json));
            r.downloadHandler = new DownloadHandlerBuffer();
            r.SetRequestHeader("Content-Type", "application/json");
            r.timeout = 2;
            yield return r.SendWebRequest();
            if (r.result != UnityWebRequest.Result.Success)
                Debug.LogWarning("[nlcl] hub unreachable (" + r.error + "): start python/main.py");
        }
    }

    IEnumerator Poller(Ch ch)
    {
        float wait = Mathf.Max(0.2f, ch.interval / 2f);
        while (true)
        {
            using (UnityWebRequest r = UnityWebRequest.Get(ch.url))
            {
                r.timeout = 2;
                yield return r.SendWebRequest();
                if (r.result == UnityWebRequest.Result.Success)
                {
                    Dictionary<string, object> msg = NlclJson.Parse(r.downloadHandler.text);
                    object t;
                    if (msg.Count > 0 && msg.TryGetValue("_t", out t))
                    {
                        double stamp = NlclEntity.ToFloat(t);
                        if (t is double) stamp = (double)t;
                        if (stamp != ch.seen) { ch.seen = stamp; Deliver(ch, msg); }
                    }
                }
            }
            yield return new WaitForSeconds(wait);
        }
    }

    // ---- receiving ------------------------------------------------------------
    /// <summary>Copy fields onto the destination entity and fire message/input behaviours.</summary>
    public static void Deliver(Ch ch, Dictionary<string, object> msg)
    {
        bool anyBool = false, rising = false;
        foreach (KeyValuePair<string, object> kv in msg)
        {
            if (kv.Key == "channel" || kv.Key == "from" || kv.Key.StartsWith("_")) continue;
            Remote[ch.src + "." + kv.Key] = kv.Value;
            if (kv.Value is bool)
            {
                anyBool = true;
                bool last;
                _lastBool.TryGetValue(ch.src + "." + kv.Key, out last);
                if ((bool)kv.Value && !last) rising = true;
                _lastBool[ch.src + "." + kv.Key] = (bool)kv.Value;
            }
        }
        NlclEntity dst = NlclWorld.Get<NlclEntity>(ch.dst);
        if (dst != null)
            foreach (KeyValuePair<string, object> kv in msg)
                if (kv.Key != "channel" && kv.Key != "from" && !kv.Key.StartsWith("_")) dst.NlclSet(kv.Key, kv.Value);
        foreach (NlclEntity e in NlclWorld.Live())
        {
            e.NlclMessage(ch.src, e == dst);
            if (rising || !anyBool) e.NlclRemoteInput(ch.src);
        }
    }
}

/// <summary>Minimal JSON for flat objects: numbers, strings, booleans, null.</summary>
public static class NlclJson
{
    public static string Write(Dictionary<string, object> d)
    {
        StringBuilder sb = new StringBuilder("{");
        bool first = true;
        foreach (KeyValuePair<string, object> kv in d)
        {
            if (!first) sb.Append(',');
            first = false;
            sb.Append(Quote(kv.Key)).Append(':');
            object v = kv.Value;
            if (v == null) sb.Append("null");
            else if (v is bool) sb.Append((bool)v ? "true" : "false");
            else if (v is float || v is double || v is int || v is long)
                sb.Append(System.Convert.ToDouble(v).ToString("R", CultureInfo.InvariantCulture));
            else sb.Append(Quote(v.ToString()));
        }
        return sb.Append('}').ToString();
    }

    static string Quote(string s)
    {
        return "\"" + s.Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("\n", "\\n") + "\"";
    }

    public static Dictionary<string, object> Parse(string json)
    {
        Dictionary<string, object> d = new Dictionary<string, object>();
        if (string.IsNullOrEmpty(json)) return d;
        int i = 0;
        Skip(json, ref i);
        if (i >= json.Length || json[i] != '{') return d;
        i++;
        while (i < json.Length)
        {
            Skip(json, ref i);
            if (i < json.Length && json[i] == '}') break;
            string key = ReadString(json, ref i);
            Skip(json, ref i);
            if (i < json.Length && json[i] == ':') i++;
            Skip(json, ref i);
            d[key] = ReadValue(json, ref i);
            Skip(json, ref i);
            if (i < json.Length && json[i] == ',') i++;
            else break;
        }
        return d;
    }

    static void Skip(string s, ref int i) { while (i < s.Length && char.IsWhiteSpace(s[i])) i++; }

    static string ReadString(string s, ref int i)
    {
        StringBuilder sb = new StringBuilder();
        if (i >= s.Length || s[i] != '"') return "";
        i++;
        while (i < s.Length && s[i] != '"')
        {
            char c = s[i++];
            if (c == '\\' && i < s.Length)
            {
                char e = s[i++];
                if (e == 'n') sb.Append('\n');
                else if (e == 't') sb.Append('\t');
                else if (e == 'u' && i + 4 <= s.Length) { sb.Append((char)System.Convert.ToInt32(s.Substring(i, 4), 16)); i += 4; }
                else sb.Append(e);
            }
            else sb.Append(c);
        }
        i++;
        return sb.ToString();
    }

    static object ReadValue(string s, ref int i)
    {
        if (i >= s.Length) return null;
        char c = s[i];
        if (c == '"') return ReadString(s, ref i);
        if (c == '{' || c == '[')
        {   // nested values are not part of the flat protocol: skip them
            int depth = 0;
            do { if (s[i] == '{' || s[i] == '[') depth++; else if (s[i] == '}' || s[i] == ']') depth--; i++; }
            while (i < s.Length && depth > 0);
            return null;
        }
        int start = i;
        while (i < s.Length && s[i] != ',' && s[i] != '}' && !char.IsWhiteSpace(s[i])) i++;
        string tok = s.Substring(start, i - start);
        if (tok == "true") return true;
        if (tok == "false") return false;
        if (tok == "null") return null;
        double num;
        if (double.TryParse(tok, NumberStyles.Float, CultureInfo.InvariantCulture, out num)) return num;
        return tok;
    }
}
